options.getOption:
// What each era left behind: the buildings standing today, by the era of
// their lot, in the map's own era colours, with each era's average roof
// height as a tick on the right-hand axis.
//
// Clicking a bar toggles that era in the dashboard's "Built in" variable
// (ERA): from All, a click keeps only that era; further clicks add or remove
// eras; removing the last one, or adding the last missing one, goes back to
// All. The map, the coverage figure and the station table follow. The chart
// never filters itself: the eras left out stay as grey bars, so there is
// always something to click back.
// The query frame has columns `era`, `buildings` and `avg_height_ft`, one row
// per era, already cut by the height floor but not by the era.
// @constants begin
const ERA = 'era';
const ALL = '$__all';
const ERAS = [
  { era: 'Pre-1900', color: '#2b3a67' },
  { era: '1900-1929', color: '#3f6c9c' },
  { era: '1930-1949', color: '#5fa0b8' },
  { era: '1950-1979', color: '#93c4a0' },
  { era: '1980-1999', color: '#e0c26b' },
  { era: '2000-2014', color: '#e08a48' },
  { era: '2015+', color: '#d1495b' },
  { era: 'Unknown', color: '#6c6c6c' },
];
const CONTEXT = 'rgba(128,128,128,0.22)';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'A') ?? context.panel.data.series[0];
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const byEra = new Map(
  col('era').map((era, i) => [
    era,
    { buildings: Number(col('buildings')[i]), height: col('avg_height_ft')[i] == null ? null : Number(col('avg_height_ft')[i]) },
  ])
);
// Every era on the axis, in order, even one the height floor emptied.
const eras = ERAS.map((e) => e.era);
const rows = eras.map((era) => byEra.get(era) ?? { buildings: 0, height: null });

// The selection, from the URL (what a click just wrote) or, before any click,
// from the variable. null stands for All.
const readPicked = () => {
  let values = new URLSearchParams(location.getLocation().search).getAll('var-' + ERA);
  if (values.length === 0) {
    try {
      values = [].concat(JSON.parse(context.grafana.replaceVariables('${' + ERA + ':json}')));
    } catch (e) {
      values = [];
    }
  }
  const picked = values.filter((v) => eras.includes(v));
  return values.includes(ALL) || picked.length === 0 || picked.length === eras.length ? null : picked;
};

// The whole column answers a click, not only the bar: the recent eras are a
// few pixels tall next to 1900-1929. Listened to on the canvas, by a named
// handler the panel removes again before it runs this code next time.
const onClick = (event) => {
  const at = [event.offsetX, event.offsetY];
  if (!chart.containPixel({ gridIndex: 0 }, at)) {
    return;
  }
  const era = eras[Math.round(chart.convertFromPixel({ gridIndex: 0 }, at)[0])];
  if (!era) {
    return;
  }
  const picked = readPicked();
  let next;
  if (picked === null) {
    next = [era];
  } else if (picked.includes(era)) {
    next = picked.filter((e) => e !== era);
  } else {
    next = eras.filter((e) => e === era || picked.includes(e));
  }
  const all = next.length === 0 || next.length === eras.length;
  location.partial({ ['var-' + ERA]: all ? ALL : next }, true);
};
const zr = chart.getZr();
zr.on('click', onClick);

const build = (picked) => ({
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 8, top: 30, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const r = rows[i];
      const height = r.height == null ? 'none standing' : `${r.height.toFixed(0)} ft`;
      const state = picked === null || picked.includes(eras[i]) ? 'click to filter' : 'left out · click to add';
      return `<b>${eras[i]}</b><br/>Buildings standing: <b>${r.buildings.toLocaleString('en-US')}</b><br/>Average roof height: ${height}<br/><span style="color:${muted}">${state}</span>`;
    },
  },
  xAxis: {
    type: 'category',
    data: eras,
    axisTick: { show: false },
    axisLabel: { color: text, fontSize: 11 },
  },
  yAxis: [
    {
      type: 'value',
      name: 'buildings',
      nameTextStyle: { color: muted },
      axisLabel: { color: muted },
      splitLine: { lineStyle: { opacity: 0.15 } },
    },
    {
      type: 'value',
      name: 'avg roof, ft',
      nameTextStyle: { color: muted },
      axisLabel: { color: muted },
      splitLine: { show: false },
    },
  ],
  series: [
    {
      type: 'bar',
      name: 'Buildings standing',
      barWidth: '62%',
      data: rows.map((r, i) => ({
        value: r.buildings,
        itemStyle: {
          color: picked === null || picked.includes(eras[i]) ? ERAS[i].color : CONTEXT,
          borderRadius: [3, 3, 0, 0],
        },
      })),
      label: { show: true, position: 'top', color: muted, fontSize: 10, formatter: (p) => Number(p.value).toLocaleString('en-US') },
    },
    {
      type: 'scatter',
      name: 'Average roof height',
      yAxisIndex: 1,
      symbol: 'rect',
      symbolSize: [26, 2],
      itemStyle: { color: text },
      data: rows.map((r) => r.height),
      silent: true,
      tooltip: { show: false },
    },
  ],
});

// A click changes only the variable; this panel's query does not read it, so
// the selection is redrawn from the URL rather than waiting for a refresh.
let drawn = JSON.stringify(readPicked());
const stop = location.getHistory().listen(() => {
  const picked = readPicked();
  const key = JSON.stringify(picked);
  if (key !== drawn && !chart.isDisposed()) {
    drawn = key;
    chart.setOption(build(picked));
  }
});

return {
  version: 2,
  option: build(readPicked()),
  unsubscribe: () => {
    stop();
    zr.off('click', onClick);
  },
};

